constexpr Distance getTrainHeadLength(TrainDirection dir) {
  // TODO: fix this value, because whatever I put, the train collide at the shared branch.
  if (dir == TrainDirection::Forward) {
    return 50'000; // 5 cm;
  }
  return 150'000; // 15cm;
}

constexpr Speed convertSpeedLevelToOfflineSpeed(TrainId trainId, SpeedLevel speedLevel) {
  switch (trainId) {
  case 13:
    return OFFLINE_SPEED_TRAIN_13[speedLevel];
  case 14:
    return OFFLINE_SPEED_TRAIN_14[speedLevel];
  case 15:
    return OFFLINE_SPEED_TRAIN_15[speedLevel];
  case 17:
    return OFFLINE_SPEED_TRAIN_17[speedLevel];
  case 18:
    return OFFLINE_SPEED_TRAIN_18[speedLevel];
  case 55:
    return OFFLINE_SPEED_TRAIN_55[speedLevel];
  default:
    return OFFLINE_SPEED_TRAIN_13[speedLevel];
  }
}

constexpr Distance getStoppingDistanceFromLevel(TrainId trainId, SpeedLevel speedLevel) {
  switch (trainId) {
  case 13:
    return STOPPING_DISTANCE_TRAIN_13[speedLevel];
  case 14:
    return STOPPING_DISTANCE_TRAIN_14[speedLevel];
  case 15:
    return STOPPING_DISTANCE_TRAIN_15[speedLevel];
  case 17:
    return STOPPING_DISTANCE_TRAIN_17[speedLevel];
  case 18:
    return STOPPING_DISTANCE_TRAIN_18[speedLevel];
  case 55:
    return STOPPING_DISTANCE_TRAIN_55[speedLevel];
  default:
    return STOPPING_DISTANCE_TRAIN_13[speedLevel];
  }
}

constexpr Distance getStoppingDistance(TrainId trainId, Speed speed) {
  for (SpeedLevel i = 1; i <= MAX_SPEED_LEVEL; ++i) {
    Speed offlineSpeed = convertSpeedLevelToOfflineSpeed(trainId, i);
    if (speed <= offlineSpeed) {
      Speed v0 = convertSpeedLevelToOfflineSpeed(trainId, i - 1);
      Speed v1 = offlineSpeed;
      Distance d0 = getStoppingDistanceFromLevel(trainId, i - 1);
      Distance d1 = getStoppingDistanceFromLevel(trainId, i);

      int64_t dS = static_cast<int64_t>(d1) - static_cast<int64_t>(d0);
      int64_t dV = static_cast<int64_t>(speed) - static_cast<int64_t>(v0);
      int64_t dX = static_cast<int64_t>(v1) - static_cast<int64_t>(v0);

      return static_cast<Distance>(d0 + ((dV * dS) / dX));
    }
  }
  return getStoppingDistanceFromLevel(trainId, MAX_SPEED_LEVEL);
}

